/bin/zsh -lc "rtk python3 -c 'import json,urllib.request,urllib.error; base=\"http://127.0.0.1:8765\"; out={};
for route in (\"/api/identity\",\"/api/run\"):
 try:
  value=json.load(urllib.request.urlopen(base+route,timeout=2));
  out[route]={k:value.get(k) for k in ((\"workspace_root\",\"jobbot_version\",\"pid\") if route.endswith(\"identity\") else (\"run_id\",\"status\",\"active\",\"stop_requested\"))};
 except Exception as exc: out[route]={\"reachable\":False,\"error\":type(exc).__name__}
print(json.dumps(out,indent=2))' && rtk ps -axo comm | rtk rg 'Google Chrome|chrome' | rtk wc -l"
